arguments.content:
/* ClipCast Design System */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

:root {
  --primary: #1868DB;
  --primary-dark: #1254b8;
  --primary-light: #e8f0fc;
  --accent: #FF613D;
  --accent-dark: #e04e2e;
  --dark: #292A2E;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-300: #d1d5db;
  --gray-400: #9ca3af;
  --gray-500: #6b7280;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-800: #1f2937;
  --gray-900: #111827;
  --white: #ffffff;
  --radius: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.10);
  --shadow-lg: 0 16px 48px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 64px rgba(0,0,0,0.14);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
img { max-width: 100%; height: auto; }
button { cursor: pointer; font-family: inherit; }
input { font-family: inherit; }

/* ——— TYPOGRAPHY ——— */
.text-xs   { font-size: 0.75rem; }
.text-sm   { font-size: 0.875rem; }
.text-base { font-size: 1rem; }
.text-lg   { font-size: 1.125rem; }
.text-xl   { font-size: 1.25rem; }
.text-2xl  { font-size: 1.5rem; }
.text-3xl  { font-size: 1.875rem; }
.text-4xl  { font-size: 2.25rem; }
.text-5xl  { font-size: 3rem; }
.text-6xl  { font-size: 3.75rem; }

.font-light   { font-weight: 300; }
.font-normal  { font-weight: 400; }
.font-medium  { font-weight: 500; }
.font-semibold{ font-weight: 600; }
.font-bold    { font-weight: 700; }
.font-extrabold{font-weight: 800; }
.font-black   { font-weight: 900; }

.leading-tight  { line-height: 1.25; }
.leading-snug   { line-height: 1.375; }
.leading-normal { line-height: 1.5; }
.leading-relaxed{ line-height: 1.625; }

.text-center { text-align: center; }
.text-left   { text-align: left; }
.text-right  { text-align: right; }

.text-primary    { color: var(--primary); }
.text-accent     { color: var(--accent); }
.text-dark       { color: var(--dark); }
.text-white      { color: var(--white); }
.text-gray-500   { color: var(--gray-500); }
.text-gray-600   { color: var(--gray-600); }
.text-gray-700   { color: var(--gray-700); }

/* ——— LAYOUT ——— */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-sm {
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-lg {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 40px;
}

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.items-start { align-items: flex-start; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.flex-wrap { flex-wrap: wrap; }
.gap-2 { gap: 8px; }
.gap-3 { gap: 12px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }
.gap-10 { gap: 40px; }
.gap-12 { gap: 48px; }

.grid { display: grid; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

.w-full { width: 100%; }
.h-full { height: 100%; }

/* ——— SPACING ——— */
.section { padding: 80px 0; }
.section-sm { padding: 48px 0; }
.section-lg { padding: 120px 0; }

.mt-2 { margin-top: 8px; }
.mt-3 { margin-top: 12px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mt-8 { margin-top: 32px; }
.mt-10 { margin-top: 40px; }
.mt-12 { margin-top: 48px; }
.mb-2 { margin-bottom: 8px; }
.mb-3 { margin-bottom: 12px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }
.mb-10 { margin-bottom: 40px; }
.mb-12 { margin-bottom: 48px; }
.mx-auto { margin-left: auto; margin-right: auto; }

/* ——— BUTTONS ——— */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.9375rem;
  transition: all 0.2s ease;
  border: none;
  white-space: nowrap;
  cursor: pointer;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
}
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(24,104,219,0.35); }

.btn-accent {
  background: var(--accent);
  color: var(--white);
}
.btn-accent:hover { background: var(--accent-dark); transform: translateY(-1px); box-shadow: 0 4px 12px rgba(255,97,61,0.35); }

.btn-outline {
  background: transparent;
  color: var(--dark);
  border: 1.5px solid var(--gray-300);
}
.btn-outline:hover { border-color: var(--primary); color: var(--primary); background: var(--primary-light); }

.btn-outline-white {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.5);
}
.btn-outline-white:hover { background: rgba(255,255,255,0.1); border-color: white; }

.btn-lg { padding: 16px 32px; font-size: 1.0625rem; border-radius: 10px; }
.btn-sm { padding: 8px 16px; font-size: 0.8125rem; border-radius: 6px; }

/* ——— BADGE ——— */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
}
.badge-primary { background: var(--primary-light); color: var(--primary); }
.badge-accent { background: #fff0ed; color: var(--accent); }
.badge-green { background: #ecfdf5; color: #059669; }
.badge-new { background: linear-gradient(135deg, var(--primary), #6366f1); color: white; }

/* ——— CARDS ——— */
.card {
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.card-border {
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1.5px solid var(--gray-200);
  overflow: hidden;
}

/* ——— NAV ——— */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow 0.2s;
}

.nav.scrolled { box-shadow: var(--shadow-md); }

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  gap: 32px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 1.25rem;
  color: var(--dark);
  flex-shrink: 0;
}

.nav-logo .logo-icon {
  width: 32px;
  height: 32px;
  background: linear-gradient(135deg, var(--primary), #6366f1);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 0.875rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  display: block;
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-700);
  transition: all 0.15s;
}
.nav-links a:hover { background: var(--gray-100); color: var(--dark); }
.nav-links a.active { color: var(--primary); }

.nav-actions { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

/* ——— HERO ——— */
.hero {
  padding-top: 140px;
  padding-bottom: 80px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  background: var(--primary-light);
  border: 1px solid rgba(24,104,219,0.2);
  border-radius: 100px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 20px;
}

.hero h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--dark);
  margin-bottom: 20px;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--primary) 0%, #6366f1 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.125rem;
  color: var(--gray-600);
  max-width: 560px;
  margin-bottom: 36px;
  line-height: 1.7;
}

/* ——— LOGO BAR ——— */
.logo-bar {
  padding: 40px 0;
  background: var(--gray-50);
  border-top: 1px solid var(--gray-200);
  border-bottom: 1px solid var(--gray-200);
}

.logo-bar-text {
  font-size: 0.875rem;
  color: var(--gray-500);
  font-weight: 500;
  margin-bottom: 24px;
  text-align: center;
}

.logo-bar-list {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.logo-bar-item {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--gray-400);
  letter-spacing: -0.01em;
  transition: color 0.2s;
}
.logo-bar-item:hover { color: var(--gray-600); }

/* ——— SECTION LABEL ——— */
.section-label {
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--dark);
  margin-bottom: 16px;
}

.section-subtitle {
  font-size: 1.0625rem;
  color: var(--gray-500);
  max-width: 560px;
  line-height: 1.7;
}

/* ——— FEATURE HIGHLIGHT ——— */
.feature-highlight {
  background: linear-gradient(135deg, var(--primary-light) 0%, #ede9fe 100%);
  border-radius: var(--radius-xl);
  padding: 56px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  overflow: hidden;
  position: relative;
}

.feature-highlight::before {
  content: '';
  position: absolute;
  top: -80px; right: -80px;
  width: 300px; height: 300px;
  background: radial-gradient(circle, rgba(99,102,241,0.15), transparent 70%);
  pointer-events: none;
}

/* ——— VIDEO MOCKUP ——— */
.video-mockup {
  background: var(--dark);
  border-radius: 12px;
  aspect-ratio: 16/10;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: var(--shadow-xl);
  position: relative;
}

.video-mockup-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: #1a1b1f;
}

.video-mockup-bar .dot {
  width: 10px; height: 10px;
  border-radius: 50%;
}

.video-mockup-bar .dot:nth-child(1) { background: #FF5F57; }
.video-mockup-bar .dot:nth-child(2) { background: #FEBC2E; }
.video-mockup-bar .dot:nth-child(3) { background: #28C840; }

.video-mockup-screen {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #1e2030, #2d3561);
  position: relative;
}

.play-btn {
  width: 56px; height: 56px;
  background: rgba(255,255,255,0.15);
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.25rem;
  cursor: pointer;
  transition: all 0.2s;
  backdrop-filter: blur(8px);
}
.play-btn:hover { background: rgba(255,255,255,0.25); transform: scale(1.1); }

/* ——— PRICING TOGGLE ——— */
.billing-toggle {
  display: inline-flex;
  background: var(--gray-100);
  border-radius: 100px;
  padding: 4px;
  gap: 0;
}

.billing-toggle button {
  padding: 8px 20px;
  border-radius: 100px;
  border: none;
  background: transparent;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-600);
  cursor: pointer;
  transition: all 0.2s;
  white-space: nowrap;
}

.billing-toggle button.active {
  background: var(--white);
  color: var(--dark);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.save-badge {
  display: inline-block;
  padding: 2px 8px;
  background: linear-gradient(135deg, var(--accent), #ff8c6e);
  color: white;
  border-radius: 100px;
  font-size: 0.6875rem;
  font-weight: 700;
  margin-left: 6px;
}

/* ——— PRICING CARDS ——— */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
}

.pricing-card {
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  background: var(--white);
  display: flex;
  flex-direction: column;
  gap: 16px;
  transition: all 0.2s;
  position: relative;
}
.pricing-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }

.pricing-card.featured {
  border-color: var(--primary);
  background: linear-gradient(180deg, var(--primary-light) 0%, var(--white) 40%);
}

.pricing-card .plan-label {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: white;
  padding: 3px 12px;
  border-radius: 100px;
  font-size: 0.6875rem;
  font-weight: 700;
  white-space: nowrap;
}

.pricing-card .plan-name {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--dark);
}

.pricing-card .plan-price {
  display: flex;
  align-items: baseline;
  gap: 2px;
}

.pricing-card .price-amount {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--dark);
  letter-spacing: -0.02em;
}

.pricing-card .price-unit {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin-left: 4px;
}

.pricing-card .plan-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.pricing-card .plan-features li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--gray-700);
}

.pricing-card .plan-features li::before {
  content: '✓';
  color: var(--primary);
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}

/* ——— COMPARISON TABLE ——— */
.comparison-table {
  width: 100%;
  border-collapse: collapse;
  border-radius: var(--radius);
  overflow: hidden;
  font-size: 0.875rem;
}

.comparison-table th {
  padding: 16px 20px;
  text-align: left;
  font-weight: 700;
  font-size: 0.875rem;
  background: var(--gray-50);
  border-bottom: 2px solid var(--gray-200);
}

.comparison-table th:first-child { border-radius: 0; }

.comparison-table td {
  padding: 14px 20px;
  border-bottom: 1px solid var(--gray-100);
  color: var(--gray-700);
}

.comparison-table tr:last-child td { border-bottom: none; }

.comparison-table tr:hover td { background: var(--gray-50); }

.comparison-table .check { color: var(--primary); font-weight: 700; font-size: 1rem; }
.comparison-table .dash { color: var(--gray-300); }

.comparison-table th.featured-col { background: var(--primary-light); color: var(--primary); }
.comparison-table td.featured-col { background: rgba(24,104,219,0.03); }

/* ——— FAQ ——— */
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  cursor: pointer;
  font-weight: 600;
  font-size: 1rem;
  color: var(--dark);
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  gap: 16px;
  transition: color 0.2s;
}
.faq-question:hover { color: var(--primary); }

.faq-icon {
  flex-shrink: 0;
  width: 24px; height: 24px;
  background: var(--gray-100);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  color: var(--gray-600);
  transition: all 0.2s;
}

.faq-item.open .faq-icon { background: var(--primary-light); color: var(--primary); transform: rotate(45deg); }

.faq-answer {
  display: none;
  padding: 0 0 20px 0;
  font-size: 0.9375rem;
  color: var(--gray-600);
  line-height: 1.7;
  max-width: 760px;
}

.faq-item.open .faq-answer { display: block; }

/* ——— TESTIMONIALS ——— */
.testimonial-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.testimonial-quote {
  font-size: 0.9375rem;
  color: var(--gray-700);
  line-height: 1.7;
  font-style: italic;
  flex: 1;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 40px; height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
  color: white;
  flex-shrink: 0;
}

.testimonial-name { font-weight: 600; font-size: 0.875rem; color: var(--dark); }
.testimonial-title { font-size: 0.8125rem; color: var(--gray-500); }

/* ——— FOOTER ——— */
.footer {
  background: var(--dark);
  color: var(--gray-400);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand p { font-size: 0.875rem; line-height: 1.7; margin-top: 12px; max-width: 220px; }

.footer-col h4 {
  font-size: 0.8125rem;
  font-weight: 700;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.footer-col a { font-size: 0.875rem; color: var(--gray-400); transition: color 0.15s; }
.footer-col a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
}

/* ——— COOKIE BANNER ——— */
.cookie-banner {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 1000;
  background: var(--dark);
  color: var(--white);
  border-radius: var(--radius-lg);
  padding: 20px 28px;
  display: flex;
  align-items: center;
  gap: 24px;
  box-shadow: var(--shadow-xl);
  max-width: 780px;
  width: calc(100% - 48px);
  border: 1px solid rgba(255,255,255,0.1);
}

.cookie-banner p { font-size: 0.875rem; line-height: 1.6; color: var(--gray-300); flex: 1; }
.cookie-banner p a { color: var(--primary); text-decoration: underline; }

.cookie-actions { display: flex; gap: 8px; flex-shrink: 0; flex-wrap: wrap; }

/* ——— MODAL ——— */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  backdrop-filter: blur(4px);
}

.modal {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 40px;
  max-width: 500px;
  width: 100%;
  box-shadow: var(--shadow-xl);
}

.modal h3 { font-size: 1.375rem; font-weight: 700; margin-bottom: 8px; }
.modal p { font-size: 0.9rem; color: var(--gray-600); margin-bottom: 24px; line-height: 1.6; }

/* ——— TOGGLE SWITCH ——— */
.toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 0;
